    20	    Message add(String channel, String to, String subject, String body, MessageStatus status) {
    21	        try (Connection connection = dataSource.getConnection();
    22	                PreparedStatement insert = connection.prepareStatement(
    23	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) RETURNING id")) {
    24	            insert.setString(1, channel);
    25	            insert.setString(2, to);
    26	            insert.setString(3, subject);
    27	            insert.setString(4, body);
    28	            insert.setString(5, status.name());
    29	            try (ResultSet generated = insert.executeQuery()) {
    30	                generated.next();
    31	                return new Message(generated.getLong("id"), channel, to, subject, body, status);
    32	            }
    33	        } catch (SQLException failure) {
    34	            throw new IllegalStateException("could not keep the message to " + to, failure);
    35	        }
    36	    }
    37	
    38	    public List<Message> all() {
    39	        try (Connection connection = dataSource.getConnection();
    40	                PreparedStatement select = connection.prepareStatement(
